        self.play(Indicate(vector), run_time=1)
        self.zoomed_camera.frame.move_to([1, 1, 0])
        self.play(Indicate(vector), run_time=1)
        self.zoomed_camera.frame.scale(2)
        self.play(Indicate(vector), run_time=1)
